def strWithout3a3b(A, B):
    result = []
    while A > 0 or B > 0:
        if A > B and A >= 2:
            result.append("aa")
            A -= 2
        elif A > 0:
            result.append("a")
            A -= 1
        if B > A and B >= 2:
            result.append("bb")
            B -= 2
        elif B > 0:
            result.append("b")
            B -= 1
    return ''.join(result)
